<?php $title="Take Attendance";require "../includes/header.php";$deps=$pdo->query("SELECT * FROM departments ORDER BY name")->fetchAll();$date=$_GET['date']??date('Y-m-d');$did=(int)($_GET['department_id']??0);$sem=(int)($_GET['semester']??5);$students=[];$existing=[];if($did){$q=$pdo->prepare("SELECT * FROM students WHERE department_id=? AND semester=? ORDER BY roll");$q->execute([$did,$sem]);$students=$q->fetchAll();if($students){$ids=array_column($students,'id');$in=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT student_id,status FROM attendance WHERE attendance_date=? AND student_id IN ($in)");$q->execute(array_merge([$date],$ids));foreach($q as $r)$existing[$r['student_id']]=$r['status'];}}?><h2>Take Attendance</h2><div class="card p-3 mb-3"><form class="row g-2"><div class="col-md-3"><label>Date</label><input type="date" name="date" value="<?=$date?>" class="form-control"></div><div class="col-md-4"><label>Department</label><select name="department_id" class="form-select" required><option value="">Select</option><?php foreach($deps as $d):?><option value="<?=$d['id']?>" <?=$did==$d['id']?'selected':''?>><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Semester</label><select name="semester" class="form-select"><?php for($i=1;$i<=8;$i++):?><option <?=$sem==$i?'selected':''?>><?=$i?></option><?php endfor;?></select></div><div class="col-md-2 align-self-end"><button class="btn btn-dark w-100">Load Students</button></div></form></div><?php if($did):?><form method="post" action="save.php"><input type="hidden" name="date" value="<?=$date?>"><div class="d-flex gap-2 mb-2"><button type="button" class="btn btn-success btn-sm" onclick="markAll('Present')">Mark All Present</button><button type="button" class="btn btn-danger btn-sm" onclick="markAll('Absent')">Mark All Absent</button><button class="btn btn-primary btn-sm">Save Attendance</button></div><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Roll</th><th>Name</th><th>Present</th><th>Absent</th></tr></thead><tbody><?php foreach($students as $s):$v=$existing[$s['id']]??'Present';?><tr><td><?=$s['roll']?></td><td><?=htmlspecialchars($s['name'])?></td><td><input type="radio" name="status[<?=$s['id']?>]" value="Present" <?=$v==='Present'?'checked':''?>></td><td><input type="radio" name="status[<?=$s['id']?>]" value="Absent" <?=$v==='Absent'?'checked':''?>></td></tr><?php endforeach;?></tbody></table></div></form><?php endif;?><?php require "../includes/footer.php";?>